#!/bin/bash
# ============================================ # BALCONAZO FRONTEND - COMANDOS RÁPIDOS # ============================================
echo " Balconazo Frontend - Comandos Rápidos" echo "========================================" echo ""
# Colores GREEN='\033[0;32m' BLUE='\033[0;34m' YELLOW='\033[1;33m' NC='\033[0m' # No Color
# Función para mostrar menú show_menu() { echo -e "${BLUE}Selecciona una opción:${NC}" echo "" echo " 1) ️ Build producción" echo " 2) Start desarrollo" echo " 3) Run tests" echo " 4) Test coverage" echo " 5) Format code (Prettier)" echo " 6) Lighthouse audit" echo " 7) Ver tamaño de bundles" echo " 8) Clean build" echo " 9) Ver documentación PRs" echo " 0) ❌ Salir" echo "" }
# Función principal main() { cd "$(dirname "$0")"
while true; do show_menu read -p "Opción: " option echo ""
case $option in 1) echo -e "${YELLOW}️ Building producción...${NC}" npm run build echo -e "${GREEN}✅ Build completado${NC}" ;; 2) echo -e "${YELLOW} Iniciando servidor de desarrollo...${NC}" echo -e "${GREEN} http://localhost:4200${NC}" npm start ;; 3) echo -e "${YELLOW} Ejecutando tests...${NC}" npm test ;; 4) echo -e "${YELLOW} Ejecutando tests con coverage...${NC}" npm run test:coverage ;; 5) echo -e "${YELLOW} Formateando código con Prettier...${NC}" npx prettier --write "src/**/*.{ts,html,scss}" echo -e "${GREEN}✅ Código formateado${NC}" ;; 6) echo -e "${YELLOW} Ejecutando Lighthouse audit...${NC}" echo "⚠️ Asegúrate de que el servidor esté corriendo (npm start)" read -p "Continuar? (y/n): " confirm if [ "$confirm" = "y" ]; then npx lighthouse http://localhost:4200 --view fi ;; 7) echo -e "${YELLOW} Analizando tamaño de bundles...${NC}" if [ -d "dist/balconazo-frontend" ]; then du -sh dist/balconazo-frontend/* else echo "⚠️ No hay build. Ejecuta 'npm run build' primero." fi ;; 8) echo -e "${YELLOW} Limpiando build...${NC}" rm -rf dist/ echo -e "${GREEN}✅ Build limpiado${NC}" ;; 9) echo -e "${YELLOW} Documentación de PRs:${NC}" echo "" echo " • PR-1-DESIGN-SYSTEM.md - Documentación completa del PR #1" echo " • PR-1-ENTREGA.md - Resumen de entrega" echo " • ../ROADMAP-FRONTEND.md - Roadmap completo (8 PRs)" echo "" read -p "Abrir PR-1-ENTREGA.md? (y/n): " open_doc if [ "$open_doc" = "y" ]; then cat PR-1-ENTREGA.md | less fi ;; 0) echo -e "${GREEN} ¡Hasta luego!${NC}" exit 0 ;; *) echo -e "${YELLOW}⚠️ Opción inválida${NC}" ;; esac
echo "" read -p "Presiona ENTER para continuar..." clear done }
# Ejecutar main

/* BALCONAZO APP - SISTEMA DE DISEÑO PROFESIONAL */

:root {
  --primary-500: #F43F5E;
  --primary-600: #E11D48;
  --primary-300: #FDA4AF;
  --primary-50: #FFF1F2;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-900: #111827;
  --success: #10B981;
  --success-light: #D1FAE5;
  --warning: #F59E0B;
  --warning-light: #FEF3C7;
  --error: #EF4444;
  --error-light: #FEE2E2;
  --info: #3B82F6;
  --info-light: #DBEAFE;
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-12: 3rem;
  --space-20: 5rem;
  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --font-medium: 500;
  --font-semibold: 600;
  --font-bold: 700;
  --font-extrabold: 800;
  --leading-tight: 1.25;
  --leading-normal: 1.5;
  --shadow-sm: 0 1px 3px 0 rgba(0,0,0,0.1);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1);
  --shadow-2xl: 0 25px 50px -12px rgba(0,0,0,0.25);
  --shadow-primary: 0 10px 30px -5px rgba(244,63,94,0.3);
  --shadow-card-hover: 0 20px 40px -10px rgba(0,0,0,0.15);
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;
  --transition-fast: 150ms cubic-bezier(0.4,0,0.2,1);
  --transition-base: 250ms cubic-bezier(0.4,0,0.2,1);
  --transition-slow: 350ms cubic-bezier(0.4,0,0.2,1);
}

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--gray-900);
}

h1, h2, h3, h4 {
  font-weight: var(--font-bold);
  line-height: var(--leading-tight);
  margin-bottom: var(--space-4);
}

h1 { font-size: var(--text-4xl); }
h2 { font-size: var(--text-3xl); }
h3 { font-size: var(--text-2xl); }

a {
  color: var(--primary-600);
  text-decoration: none;
}

button { font-family: inherit; cursor: pointer; }

.container {
  width: 100%;
  max-width: 1280px;

/* ============================================
   BALCONAZO APP - DESIGN SYSTEM
   Professional design system with tokens
   ============================================ */

/* Import design tokens, utilities, and animations */
@use 'styles/tokens';
@use 'styles/utilities';
@use 'styles/animations';

/* ========== GLOBAL RESET ========== */

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  font-weight: var(--font-normal);
  line-height: var(--leading-normal);
  color: var(--gray-900);
  background-color: var(--white);
  overflow-x: hidden;
}

/* ========== TYPOGRAPHY ========== */

h1, h2, h3, h4, h5, h6 {
  font-weight: var(--font-bold);
  line-height: var(--leading-tight);
  margin-bottom: var(--space-4);
  color: var(--gray-900);
}

h1 { font-size: var(--text-4xl); }
h2 { font-size: var(--text-3xl); }
h3 { font-size: var(--text-2xl); }
h4 { font-size: var(--text-xl); }
h5 { font-size: var(--text-lg); }
h6 { font-size: var(--text-base); }

p {
  margin-bottom: var(--space-4);
  color: var(--gray-700);
}

a {
  color: var(--primary-600);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--primary-700);
}

a:focus-visible {
  outline: 2px solid var(--primary-600);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

strong, b {
  font-weight: var(--font-semibold);
}

small {
  font-size: var(--text-sm);
}

/* ========== BUTTONS ========== */

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  padding: 0;
  font-size: inherit;
}

button:disabled {
  opacity: var(--opacity-disabled);
  cursor: not-allowed;
}

button:focus-visible {
  outline: 2px solid var(--primary-600);
  outline-offset: 2px;
}

/* ========== FORMS ========== */

input, textarea, select {
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  color: inherit;
}

input:focus, textarea:focus, select:focus {
  outline: none;
}

label {
  display: block;
  font-weight: var(--font-medium);
  margin-bottom: var(--space-2);
  color: var(--gray-700);
}

/* ========== IMAGES ========== */

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* ========== LAYOUT CONTAINERS ========== */

.container {
  width: 100%;
  max-width: var(--container-xl);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

@media (max-width: 640px) {
  .container {
    padding: 0 var(--space-4);
  }
}

/* ========== COMPONENT STYLES (legacy from existing app, kept for compatibility) ========== */

/* Navbar - will be replaced by new Navbar component in PR#4 */
.navbar {
  position: sticky;
  top: 0;
  height: var(--navbar-height);
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-200);
  z-index: var(--z-sticky);
  transition: all var(--transition-base);
}

.navbar-container {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.navbar-logo {
  font-size: var(--text-2xl);
  font-weight: var(--font-extrabold);
  background: linear-gradient(135deg, var(--primary-600), var(--primary-500));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  letter-spacing: var(--tracking-tight);
}

.navbar-menu {
  display: flex;
  gap: var(--space-8);
  list-style: none;
  margin: 0;
}

.navbar-link {
  color: var(--gray-700);
  font-weight: var(--font-medium);
  transition: color var(--transition-fast);
  padding: var(--space-2) 0;
  position: relative;
}

.navbar-link:hover {
  color: var(--primary-600);
}

.navbar-link.active::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--primary-600);
  border-radius: var(--radius-full);
}

/* Buttons - Enhanced */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-weight: var(--font-semibold);
  font-size: var(--text-base);
  border-radius: var(--radius-lg);
  min-height: 44px;
  border: none;
  cursor: pointer;
  transition: all var(--transition-base);
  text-decoration: none;
  white-space: nowrap;
}

.btn:disabled {
  opacity: var(--opacity-disabled);
  cursor: not-allowed;
  transform: none !important;
}

.btn-primary {
  background: linear-gradient(135deg, var(--primary-600), var(--primary-500));
  color: var(--white);
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover:not(:disabled) {
  box-shadow: var(--shadow-primary);
  transform: translateY(-2px);
}

.btn-primary:active:not(:disabled) {
  transform: translateY(0);
}

.btn-secondary {
  background: var(--gray-100);
  color: var(--gray-900);
  border: 1px solid var(--gray-300);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--gray-200);
  border-color: var(--gray-400);
}

.btn-ghost {
  background: transparent;
  color: var(--gray-700);
}

.btn-ghost:hover:not(:disabled) {
  background: var(--gray-100);
}

.btn-danger {
  background: var(--error);
  color: var(--white);
}

.btn-danger:hover:not(:disabled) {
  background: var(--error-dark);
}

.btn-success {
  background: var(--success);
  color: var(--white);
}

.btn-success:hover:not(:disabled) {
  background: var(--success-dark);
}

.btn-lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-lg);
  min-height: 52px;
}

.btn-sm {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-sm);
  min-height: 36px;
}

.btn-icon {
  padding: var(--space-3);
  min-height: 44px;
  width: 44px;
}

/* Hero Section */
.hero {
  min-height: 600px;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--primary-50) 0%, var(--gray-50) 100%);
  padding: var(--space-20) 0;
  position: relative;
}

.hero-content {
  text-align: center;
  max-width: 850px;
  margin: 0 auto;
}

.hero-title {
  font-size: var(--text-5xl);
  margin-bottom: var(--space-6);
  line-height: var(--leading-tight);
}

.hero-subtitle {
  font-size: var(--text-xl);
  color: var(--gray-600);
  margin-bottom: var(--space-8);
  line-height: var(--leading-relaxed);
}

/* Search Bar */
.search-bar {
  background: var(--white);
  border-radius: var(--radius-2xl);
  box-shadow: var(--shadow-xl);
  padding: var(--space-2);
  display: flex;
  gap: var(--space-2);
  max-width: 850px;
  margin: 0 auto;
  align-items: stretch;
}

.search-input-group {
  flex: 1;
  padding: var(--space-3) var(--space-4);
  border-right: 1px solid var(--gray-200);
  transition: background var(--transition-fast);
  border-radius: var(--radius-lg);
  min-width: 0;
}

.search-input-group:hover {
  background: var(--gray-50);
}

.search-input-group:last-of-type {
  border-right: none;
}

.search-input-label {
  font-size: var(--text-xs);
  font-weight: var(--font-bold);
  color: var(--gray-900);
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: var(--space-1);
  margin-bottom: var(--space-2);
  letter-spacing: var(--tracking-wide);
}

.search-input-label svg {
  color: var(--primary-600);
}

.search-input {
  border: none;
  outline: none;
  font-size: var(--text-base);
  width: 100%;
  background: transparent;
  font-weight: var(--font-medium);
  color: var(--gray-900);
}

.search-input::placeholder {
  color: var(--gray-400);
  font-weight: var(--font-normal);
}

.search-input:focus {
  color: var(--primary-600);
}

.search-input[type="number"] {
  -moz-appearance: textfield;
}

.search-input[type="number"]::-webkit-outer-spin-button,
.search-input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.search-input[type="date"] {
  cursor: pointer;
}

.search-input[type="date"]::-webkit-calendar-picker-indicator {
  cursor: pointer;
  filter: invert(0.5);
  transition: filter var(--transition-fast);
}

.search-input[type="date"]:hover::-webkit-calendar-picker-indicator {
  filter: invert(0.3);
}

.search-btn {
  flex-shrink: 0;
  box-shadow: 0 4px 12px rgba(244, 63, 94, 0.3);
  transition: all var(--transition-base);
  border-radius: var(--radius-xl);
  padding: var(--space-4);
  background: linear-gradient(135deg, var(--primary-600), var(--primary-500));
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
}

.search-btn:hover {
  transform: scale(1.05);
  box-shadow: 0 8px 20px rgba(244, 63, 94, 0.4);
}

.search-btn:active {
  transform: scale(0.98);
}

.search-btn svg {
  transition: transform var(--transition-fast);
}

.search-btn:hover svg {
  transform: rotate(90deg);
}

/* Space Card - Enhanced */
.space-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  cursor: pointer;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
  height: 100%;
}

.space-card:hover {
  box-shadow: var(--shadow-card-hover);
  transform: translateY(-8px);
}

.space-card-image-wrapper {
  position: relative;
  width: 100%;
  padding-top: 66.67%;
  background: var(--gray-200);
  overflow: hidden;
}

.space-card-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.space-card:hover .space-card-image {
  transform: scale(1.1);
}

.space-card-body {
  padding: var(--space-5);
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

/* Mobile Responsive */
@media (max-width: 767px) {
  .hero {
    min-height: 500px;
    padding: var(--space-12) 0;
  }

  .hero-title {
    font-size: var(--text-3xl);
  }

  .hero-subtitle {
    font-size: var(--text-lg);
  }

  .search-bar {
    flex-direction: column;
    padding: var(--space-4);
  }

  .search-input-group {
    border-right: none;
    border-bottom: 1px solid var(--gray-200);
  }

  .search-input-group:last-of-type {
    border-bottom: none;
  }

  .search-btn {
    width: 100%;
  }

  .navbar {
    height: 64px;
  }

  .navbar-logo {
    font-size: var(--text-xl);
  }
}

/* Tablet Responsive */
@media (min-width: 768px) and (max-width: 1023px) {
  .hero-title {
    font-size: var(--text-4xl);
  }
}

/* ========== FORM COMPONENTS ========== */

.form-group {
  margin-bottom: var(--space-6);
}

.form-label {
  display: block;
  font-weight: var(--font-medium);
  color: var(--gray-700);
  margin-bottom: var(--space-2);
  font-size: var(--text-sm);
}

.form-input,
.form-textarea,
.form-select {
  width: 100%;
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-base);
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-lg);
  background: var(--white);
  transition: all var(--transition-fast);
  font-family: inherit;
}

.form-input:focus,
.form-textarea:focus,
.form-select:focus {
  outline: none;
  border-color: var(--primary-600);
  box-shadow: 0 0 0 3px var(--primary-100);
}

.form-input:disabled,
.form-textarea:disabled,
.form-select:disabled {
  background: var(--gray-100);
  cursor: not-allowed;
  opacity: var(--opacity-disabled);
}

.form-error {
  color: var(--error);
  font-size: var(--text-sm);
  margin-top: var(--space-2);
}

.form-help {
  color: var(--gray-500);
  font-size: var(--text-sm);
  margin-top: var(--space-2);
}

/* ========== BADGES & CHIPS ========== */

.badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-1) var(--space-3);
  font-size: var(--text-xs);
  font-weight: var(--font-semibold);
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
}

.badge-success {
  background: var(--success-light);
  color: var(--success-dark);
}

.badge-warning {
  background: var(--warning-light);
  color: var(--warning-dark);
}

.badge-error {
  background: var(--error-light);
  color: var(--error-dark);
}

.badge-info {
  background: var(--info-light);
  color: var(--info-dark);
}

.badge-gray {
  background: var(--gray-200);
  color: var(--gray-700);
}

/* ========== CARDS ========== */

.card {
  background: var(--white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-sm);
  padding: var(--space-6);
  transition: box-shadow var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-md);
}

.card-header {
  margin-bottom: var(--space-4);
  padding-bottom: var(--space-4);
  border-bottom: 1px solid var(--gray-200);
}

.card-title {
  font-size: var(--text-xl);
  font-weight: var(--font-semibold);
  color: var(--gray-900);
  margin: 0;
}

/* ========== END OF GLOBAL STYLES ========== */

/* ============================================
   BALCONAZO - ANIMATIONS
   Animaciones y transiciones reutilizables
   ============================================ */

/* ========== KEYFRAMES ========== */

/* Fade In */
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Fade In Up */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Fade In Down */
@keyframes fadeInDown {
  from {
    opacity: 0;
    transform: translateY(-20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Slide In Right */
@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* Slide In Left */
@keyframes slideInLeft {
  from {
    opacity: 0;
    transform: translateX(-30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* Scale In */
@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Skeleton Pulse */
@keyframes skeletonPulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

/* Shimmer (for loading states) */
@keyframes shimmer {
  0% {
    background-position: -1000px 0;
  }
  100% {
    background-position: 1000px 0;
  }
}

/* Spin (for loaders) */
@keyframes spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* Bounce */
@keyframes bounce {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

/* Wiggle */
@keyframes wiggle {
  0%, 100% {
    transform: rotate(0deg);
  }
  25% {
    transform: rotate(-3deg);
  }
  75% {
    transform: rotate(3deg);
  }
}

/* Heartbeat */
@keyframes heartbeat {
  0%, 100% {
    transform: scale(1);
  }
  10%, 30% {
    transform: scale(1.1);
  }
  20%, 40% {
    transform: scale(1);
  }
}

/* ========== ANIMATION CLASSES ========== */

/* Fade animations */
.animate-fade-in {
  animation: fadeIn var(--transition-base) var(--ease-out);
}

.animate-fade-in-up {
  animation: fadeInUp var(--transition-slow) var(--ease-out);
}

.animate-fade-in-down {
  animation: fadeInDown var(--transition-slow) var(--ease-out);
}

/* Slide animations */
.animate-slide-in-right {
  animation: slideInRight var(--transition-slow) var(--ease-out);
}

.animate-slide-in-left {
  animation: slideInLeft var(--transition-slow) var(--ease-out);
}

/* Scale animation */
.animate-scale-in {
  animation: scaleIn var(--transition-base) var(--ease-out);
}

/* Skeleton pulse */
.animate-skeleton-pulse {
  animation: skeletonPulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

/* Shimmer */
.animate-shimmer {
  animation: shimmer 2s linear infinite;
  background: linear-gradient(
    to right,
    var(--gray-200) 0%,
    var(--gray-100) 50%,
    var(--gray-200) 100%
  );
  background-size: 1000px 100%;
}

/* Spin */
.animate-spin {
  animation: spin 1s linear infinite;
}

/* Bounce */
.animate-bounce {
  animation: bounce 1s ease-in-out infinite;
}

/* Wiggle */
.animate-wiggle {
  animation: wiggle 0.5s ease-in-out;
}

/* Heartbeat */
.animate-heartbeat {
  animation: heartbeat 1.5s ease-in-out infinite;
}

/* ========== ANIMATION DELAYS ========== */
.delay-75 {
  animation-delay: 75ms;
}

.delay-100 {
  animation-delay: 100ms;
}

.delay-150 {
  animation-delay: 150ms;
}

.delay-200 {
  animation-delay: 200ms;
}

.delay-300 {
  animation-delay: 300ms;
}

.delay-500 {
  animation-delay: 500ms;
}

/* ========== HOVER/FOCUS TRANSITIONS ========== */

/* Hover lift effect */
.hover-lift {
  transition: transform var(--transition-base) var(--ease-out),
              box-shadow var(--transition-base) var(--ease-out);
}

.hover-lift:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

/* Hover scale effect */
.hover-scale {
  transition: transform var(--transition-base) var(--ease-out);
}

.hover-scale:hover {
  transform: scale(1.05);
}

/* Hover brightness effect */
.hover-brightness {
  transition: filter var(--transition-base) var(--ease-out);
}

.hover-brightness:hover {
  filter: brightness(1.1);
}

/* Hover opacity effect */
.hover-opacity {
  transition: opacity var(--transition-base) var(--ease-out);
}

.hover-opacity:hover {
  opacity: var(--opacity-hover);
}

/* ========== LOADING STATES ========== */

/* Skeleton loader */
.skeleton {
  background: linear-gradient(
    90deg,
    var(--gray-200) 25%,
    var(--gray-100) 50%,
    var(--gray-200) 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.5s ease-in-out infinite;
  border-radius: var(--radius-base);
}

.skeleton-text {
  height: 1em;
  margin-bottom: 0.5em;
  border-radius: var(--radius-sm);
}

.skeleton-circle {
  border-radius: var(--radius-full);
  aspect-ratio: 1 / 1;
}

/* ========== MODAL/OVERLAY ANIMATIONS ========== */

/* Modal backdrop fade */
@keyframes modalBackdropFadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.modal-backdrop-enter {
  animation: modalBackdropFadeIn var(--transition-base) var(--ease-out);
}

/* Modal content scale */
@keyframes modalContentScaleIn {
  from {
    opacity: 0;
    transform: scale(0.9);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.modal-content-enter {
  animation: modalContentScaleIn var(--transition-base) var(--ease-out);
}

/* ========== TOAST/NOTIFICATION ANIMATIONS ========== */

@keyframes toastSlideInRight {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

.toast-enter {
  animation: toastSlideInRight var(--transition-base) var(--ease-out);
}

/* ========== PAGE TRANSITIONS ========== */

.page-enter {
  animation: fadeInUp var(--transition-slow) var(--ease-out);
}

/* ========== STAGGER ANIMATIONS (use with nth-child) ========== */

.stagger-item:nth-child(1) { animation-delay: 0ms; }
.stagger-item:nth-child(2) { animation-delay: 50ms; }
.stagger-item:nth-child(3) { animation-delay: 100ms; }
.stagger-item:nth-child(4) { animation-delay: 150ms; }
.stagger-item:nth-child(5) { animation-delay: 200ms; }
.stagger-item:nth-child(6) { animation-delay: 250ms; }
.stagger-item:nth-child(7) { animation-delay: 300ms; }
.stagger-item:nth-child(8) { animation-delay: 350ms; }

/* ========== FOCUS ANIMATIONS (Accessibility) ========== */

.focus-ring {
  transition: box-shadow var(--transition-fast) var(--ease-out);
}

.focus-ring:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--primary-300);
}

/* ========== REDUCED MOTION (Accessibility) ========== */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ============================================
   BALCONAZO DESIGN SYSTEM - TOKENS
   Design tokens organizados por categoría
   ============================================ */

:root {
  /* ========== COLORES ========== */

  /* Primary (Rose) */
  --primary-50: #FFF1F2;
  --primary-100: #FFE4E6;
  --primary-200: #FECDD3;
  --primary-300: #FDA4AF;
  --primary-400: #FB7185;
  --primary-500: #F43F5E;
  --primary-600: #E11D48;
  --primary-700: #BE123C;
  --primary-800: #9F1239;
  --primary-900: #881337;

  /* Gray Scale */
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;

  /* Semantic Colors */
  --success: #10B981;
  --success-light: #D1FAE5;
  --success-dark: #047857;

  --warning: #F59E0B;
  --warning-light: #FEF3C7;
  --warning-dark: #D97706;

  --error: #EF4444;
  --error-light: #FEE2E2;
  --error-dark: #DC2626;

  --info: #3B82F6;
  --info-light: #DBEAFE;
  --info-dark: #2563EB;

  /* Neutral */
  --white: #FFFFFF;
  --black: #000000;

  /* ========== SPACING ========== */
  --space-0: 0;
  --space-1: 0.25rem;    /* 4px */
  --space-2: 0.5rem;     /* 8px */
  --space-3: 0.75rem;    /* 12px */
  --space-4: 1rem;       /* 16px */
  --space-5: 1.25rem;    /* 20px */
  --space-6: 1.5rem;     /* 24px */
  --space-7: 1.75rem;    /* 28px */
  --space-8: 2rem;       /* 32px */
  --space-10: 2.5rem;    /* 40px */
  --space-12: 3rem;      /* 48px */
  --space-16: 4rem;      /* 64px */
  --space-20: 5rem;      /* 80px */
  --space-24: 6rem;      /* 96px */
  --space-32: 8rem;      /* 128px */

  /* ========== TIPOGRAFÍA ========== */

  /* Font Families */
  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
  --font-mono: 'SF Mono', Monaco, 'Cascadia Code', 'Roboto Mono', Consolas, 'Courier New', monospace;

  /* Font Sizes */
  --text-xs: 0.75rem;     /* 12px */
  --text-sm: 0.875rem;    /* 14px */
  --text-base: 1rem;      /* 16px */
  --text-lg: 1.125rem;    /* 18px */
  --text-xl: 1.25rem;     /* 20px */
  --text-2xl: 1.5rem;     /* 24px */
  --text-3xl: 1.875rem;   /* 30px */
  --text-4xl: 2.25rem;    /* 36px */
  --text-5xl: 3rem;       /* 48px */
  --text-6xl: 3.75rem;    /* 60px */

  /* Font Weights */
  --font-light: 300;
  --font-normal: 400;
  --font-medium: 500;
  --font-semibold: 600;
  --font-bold: 700;
  --font-extrabold: 800;
  --font-black: 900;

  /* Line Heights */
  --leading-none: 1;
  --leading-tight: 1.25;
  --leading-snug: 1.375;
  --leading-normal: 1.5;
  --leading-relaxed: 1.625;
  --leading-loose: 2;

  /* Letter Spacing */
  --tracking-tighter: -0.05em;
  --tracking-tight: -0.025em;
  --tracking-normal: 0;
  --tracking-wide: 0.025em;
  --tracking-wider: 0.05em;
  --tracking-widest: 0.1em;

  /* ========== SHADOWS ========== */
  --shadow-xs: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
  --shadow-2xl: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
  --shadow-inner: inset 0 2px 4px 0 rgba(0, 0, 0, 0.06);
  --shadow-none: none;

  /* Custom shadows */
  --shadow-primary: 0 10px 30px -5px rgba(244, 63, 94, 0.3);
  --shadow-card: var(--shadow-md);
  --shadow-card-hover: 0 20px 40px -10px rgba(0, 0, 0, 0.15);
  --shadow-navbar: 0 2px 8px rgba(0, 0, 0, 0.08);

  /* ========== BORDER RADIUS ========== */
  --radius-none: 0;
  --radius-sm: 0.25rem;     /* 4px */
  --radius-base: 0.5rem;    /* 8px */
  --radius-md: 0.625rem;    /* 10px */
  --radius-lg: 0.75rem;     /* 12px */
  --radius-xl: 1rem;        /* 16px */
  --radius-2xl: 1.5rem;     /* 24px */
  --radius-3xl: 2rem;       /* 32px */
  --radius-full: 9999px;

  /* ========== Z-INDEX ========== */
  --z-dropdown: 1000;
  --z-sticky: 1020;
  --z-fixed: 1030;
  --z-modal-backdrop: 1040;
  --z-modal: 1050;
  --z-popover: 1060;
  --z-tooltip: 1070;

  /* ========== TRANSITIONS ========== */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slower: 500ms cubic-bezier(0.4, 0, 0.2, 1);

  /* Easing functions */
  --ease-in: cubic-bezier(0.4, 0, 1, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);

  /* ========== BREAKPOINTS (reference, use in media queries) ========== */
  /* --breakpoint-sm: 640px;  */
  /* --breakpoint-md: 768px;  */
  /* --breakpoint-lg: 1024px; */
  /* --breakpoint-xl: 1280px; */
  /* --breakpoint-2xl: 1536px; */

  /* ========== LAYOUT ========== */
  --container-sm: 640px;
  --container-md: 768px;
  --container-lg: 1024px;
  --container-xl: 1280px;
  --container-2xl: 1536px;

  --navbar-height: 72px;
  --footer-height: 300px;

  /* ========== OTROS ========== */
  --opacity-disabled: 0.5;
  --opacity-hover: 0.8;
}

/* ============================================
   BALCONAZO - UTILITY CLASSES
   Clases helper reutilizables
   ============================================ */

/* ========== DISPLAY ========== */
.flex { display: flex; }
.inline-flex { display: inline-flex; }
.grid { display: grid; }
.inline-grid { display: inline-grid; }
.block { display: block; }
.inline-block { display: inline-block; }
.inline { display: inline; }
.hidden { display: none; }

/* ========== FLEX UTILITIES ========== */
.flex-row { flex-direction: row; }
.flex-col { flex-direction: column; }
.flex-wrap { flex-wrap: wrap; }
.flex-nowrap { flex-wrap: nowrap; }

.items-start { align-items: flex-start; }
.items-center { align-items: center; }
.items-end { align-items: flex-end; }
.items-stretch { align-items: stretch; }
.items-baseline { align-items: baseline; }

.justify-start { justify-content: flex-start; }
.justify-center { justify-content: center; }
.justify-end { justify-content: flex-end; }
.justify-between { justify-content: space-between; }
.justify-around { justify-content: space-around; }
.justify-evenly { justify-content: space-evenly; }

.flex-1 { flex: 1 1 0%; }
.flex-auto { flex: 1 1 auto; }
.flex-none { flex: none; }

/* ========== GAP ========== */
.gap-1 { gap: var(--space-1); }
.gap-2 { gap: var(--space-2); }
.gap-3 { gap: var(--space-3); }
.gap-4 { gap: var(--space-4); }
.gap-5 { gap: var(--space-5); }
.gap-6 { gap: var(--space-6); }
.gap-8 { gap: var(--space-8); }
.gap-12 { gap: var(--space-12); }

/* ========== GRID ========== */
.grid-cols-1 { grid-template-columns: repeat(1, minmax(0, 1fr)); }
.grid-cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-cols-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.grid-cols-5 { grid-template-columns: repeat(5, minmax(0, 1fr)); }

@media (min-width: 768px) {
  .md\:grid-cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .md\:grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .md\:grid-cols-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}

@media (min-width: 1024px) {
  .lg\:grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .lg\:grid-cols-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .lg\:grid-cols-5 { grid-template-columns: repeat(5, minmax(0, 1fr)); }
}

/* ========== SPACING (Margin & Padding) ========== */
.m-0 { margin: 0; }
.m-auto { margin: auto; }
.mx-auto { margin-left: auto; margin-right: auto; }

.p-0 { padding: 0; }
.p-2 { padding: var(--space-2); }
.p-4 { padding: var(--space-4); }
.p-6 { padding: var(--space-6); }
.p-8 { padding: var(--space-8); }

.px-2 { padding-left: var(--space-2); padding-right: var(--space-2); }
.px-4 { padding-left: var(--space-4); padding-right: var(--space-4); }
.px-6 { padding-left: var(--space-6); padding-right: var(--space-6); }
.px-8 { padding-left: var(--space-8); padding-right: var(--space-8); }

.py-2 { padding-top: var(--space-2); padding-bottom: var(--space-2); }
.py-4 { padding-top: var(--space-4); padding-bottom: var(--space-4); }
.py-6 { padding-top: var(--space-6); padding-bottom: var(--space-6); }
.py-8 { padding-top: var(--space-8); padding-bottom: var(--space-8); }

.mt-2 { margin-top: var(--space-2); }
.mt-4 { margin-top: var(--space-4); }
.mt-6 { margin-top: var(--space-6); }
.mt-8 { margin-top: var(--space-8); }

.mb-2 { margin-bottom: var(--space-2); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-6 { margin-bottom: var(--space-6); }
.mb-8 { margin-bottom: var(--space-8); }

/* ========== WIDTH & HEIGHT ========== */
.w-full { width: 100%; }
.w-auto { width: auto; }
.w-screen { width: 100vw; }

.h-full { height: 100%; }
.h-auto { height: auto; }
.h-screen { height: 100vh; }

.min-h-screen { min-height: 100vh; }

/* ========== POSITION ========== */
.relative { position: relative; }
.absolute { position: absolute; }
.fixed { position: fixed; }
.sticky { position: sticky; }

.top-0 { top: 0; }
.right-0 { right: 0; }
.bottom-0 { bottom: 0; }
.left-0 { left: 0; }

.inset-0 { top: 0; right: 0; bottom: 0; left: 0; }

/* ========== OVERFLOW ========== */
.overflow-hidden { overflow: hidden; }
.overflow-auto { overflow: auto; }
.overflow-scroll { overflow: scroll; }
.overflow-x-auto { overflow-x: auto; }
.overflow-y-auto { overflow-y: auto; }

/* ========== TEXT ALIGNMENT ========== */
.text-left { text-align: left; }
.text-center { text-align: center; }
.text-right { text-align: right; }
.text-justify { text-align: justify; }

/* ========== TEXT SIZE ========== */
.text-xs { font-size: var(--text-xs); }
.text-sm { font-size: var(--text-sm); }
.text-base { font-size: var(--text-base); }
.text-lg { font-size: var(--text-lg); }
.text-xl { font-size: var(--text-xl); }
.text-2xl { font-size: var(--text-2xl); }
.text-3xl { font-size: var(--text-3xl); }
.text-4xl { font-size: var(--text-4xl); }
.text-5xl { font-size: var(--text-5xl); }

/* ========== TEXT WEIGHT ========== */
.font-light { font-weight: var(--font-light); }
.font-normal { font-weight: var(--font-normal); }
.font-medium { font-weight: var(--font-medium); }
.font-semibold { font-weight: var(--font-semibold); }
.font-bold { font-weight: var(--font-bold); }
.font-extrabold { font-weight: var(--font-extrabold); }

/* ========== TEXT COLOR ========== */
.text-gray-400 { color: var(--gray-400); }
.text-gray-500 { color: var(--gray-500); }
.text-gray-600 { color: var(--gray-600); }
.text-gray-700 { color: var(--gray-700); }
.text-gray-900 { color: var(--gray-900); }
.text-primary { color: var(--primary-600); }
.text-white { color: var(--white); }
.text-success { color: var(--success); }
.text-error { color: var(--error); }
.text-warning { color: var(--warning); }

/* ========== BACKGROUND COLOR ========== */
.bg-white { background-color: var(--white); }
.bg-gray-50 { background-color: var(--gray-50); }
.bg-gray-100 { background-color: var(--gray-100); }
.bg-gray-200 { background-color: var(--gray-200); }
.bg-primary { background-color: var(--primary-600); }
.bg-primary-light { background-color: var(--primary-50); }
.bg-success { background-color: var(--success); }
.bg-success-light { background-color: var(--success-light); }
.bg-error { background-color: var(--error); }
.bg-error-light { background-color: var(--error-light); }
.bg-warning { background-color: var(--warning); }
.bg-warning-light { background-color: var(--warning-light); }

/* ========== BORDER ========== */
.border { border: 1px solid var(--gray-200); }
.border-2 { border: 2px solid var(--gray-200); }
.border-t { border-top: 1px solid var(--gray-200); }
.border-b { border-bottom: 1px solid var(--gray-200); }
.border-l { border-left: 1px solid var(--gray-200); }
.border-r { border-right: 1px solid var(--gray-200); }

.border-gray-200 { border-color: var(--gray-200); }
.border-gray-300 { border-color: var(--gray-300); }
.border-primary { border-color: var(--primary-600); }

/* ========== BORDER RADIUS ========== */
.rounded { border-radius: var(--radius-base); }
.rounded-sm { border-radius: var(--radius-sm); }
.rounded-md { border-radius: var(--radius-md); }
.rounded-lg { border-radius: var(--radius-lg); }
.rounded-xl { border-radius: var(--radius-xl); }
.rounded-2xl { border-radius: var(--radius-2xl); }
.rounded-full { border-radius: var(--radius-full); }

/* ========== SHADOW ========== */
.shadow-sm { box-shadow: var(--shadow-sm); }
.shadow { box-shadow: var(--shadow-md); }
.shadow-md { box-shadow: var(--shadow-md); }
.shadow-lg { box-shadow: var(--shadow-lg); }
.shadow-xl { box-shadow: var(--shadow-xl); }
.shadow-2xl { box-shadow: var(--shadow-2xl); }
.shadow-none { box-shadow: none; }

/* ========== OPACITY ========== */
.opacity-0 { opacity: 0; }
.opacity-50 { opacity: 0.5; }
.opacity-75 { opacity: 0.75; }
.opacity-100 { opacity: 1; }

/* ========== CURSOR ========== */
.cursor-pointer { cursor: pointer; }
.cursor-not-allowed { cursor: not-allowed; }
.cursor-default { cursor: default; }

/* ========== POINTER EVENTS ========== */
.pointer-events-none { pointer-events: none; }
.pointer-events-auto { pointer-events: auto; }

/* ========== USER SELECT ========== */
.select-none { user-select: none; }
.select-text { user-select: text; }
.select-all { user-select: all; }

/* ========== TRANSITIONS ========== */
.transition {
  transition-property: all;
  transition-duration: var(--transition-base);
  transition-timing-function: var(--ease-in-out);
}

.transition-fast {
  transition-duration: var(--transition-fast);
}

.transition-slow {
  transition-duration: var(--transition-slow);
}

/* ========== RESPONSIVE UTILITIES ========== */
@media (max-width: 767px) {
  .hide-mobile { display: none !important; }
}

@media (min-width: 768px) {
  .hide-desktop { display: none !important; }
  .show-desktop { display: block; }
}

/* ========== TRUNCATE TEXT ========== */
.truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.line-clamp-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.line-clamp-3 {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ========== ASPECT RATIO ========== */
.aspect-square {
  aspect-ratio: 1 / 1;
}

.aspect-video {
  aspect-ratio: 16 / 9;
}

.aspect-4-3 {
  aspect-ratio: 4 / 3;
}

/* ========== OBJECT FIT ========== */
.object-cover { object-fit: cover; }
.object-contain { object-fit: contain; }
.object-fill { object-fit: fill; }

/* ========== Z-INDEX ========== */
.z-0 { z-index: 0; }
.z-10 { z-index: 10; }
.z-20 { z-index: 20; }
.z-30 { z-index: 30; }
.z-40 { z-index: 40; }
.z-50 { z-index: 50; }
.z-dropdown { z-index: var(--z-dropdown); }
.z-modal { z-index: var(--z-modal); }

/* ========== ACCESSIBILITY ========== */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* Focus visible for accessibility */
.focus-visible:focus-visible {
  outline: 2px solid var(--primary-600);
  outline-offset: 2px;
}
